#!/usr/bin/env python3
"""Deterministic metadata/report layer; never replaces independently extracted votes."""
import sys
sys.dont_write_bytecode=True
import json
from reciprocal import O,T,S,oj,enc,sha

def status():
 p=json.loads((T/'peer-reconciliation.json').read_bytes())
 return dict(peer_agent_id=p['peer_agent_id'],status=p['status'],scope='Frozen final peer source core only; historical normalization differences explicit; not calculator/scenarios/live/future equality',peer_manifest_sha256='c725c0069e8409d9667ef0ce674a14bea20456410bdee4e50eb0e44b4e5846b9',peer_original_first_witness_sha256=p['peer_original_first_witness_sha256'],proof_path='peer-reconciliation.json',full_evidence_path=p['full_evidence']['path'],canonical_statewide_native_agreement=False,coordinator_acceptance=False)

def main():
 review=json.loads((T/'peer-reconciliation.json').read_bytes());c=review['counts'];contract=oj('priority-set.json');contract['peer_agreement']=status();(T/'priority-set.json').write_bytes(enc(contract))
 report=O.read('turnout.md').decode();report=report.replace('**Peer ID remains null, reciprocal peer agreement is pending, and coordinator acceptance is pending.** This is the bounded original-first worker package;', '**The bounded reciprocal source-core review is complete; coordinator acceptance remains pending.** The original-first package is preserved byte-exact in the immutable history;')
 report+='''\n## Bounded reciprocal source-core review — 20 October 2026\n\nThe actual independent baseline worker was `7c03df8c-f908-40a8-a289-369e4aa26e69`. Its completed, repaired final package was captured before comparison: manifest `c725c0069e8409d9667ef0ce674a14bea20456410bdee4e50eb0e44b4e5846b9`, original-first witness `208a3ad98dfb055eea0f895c0c0faf9881f684214e7d5a34c41e01f4df123b7f`. All 600 peer bodies are frozen as provenance. Agreement covers the source core described here; it does not cover every peer artifact, calculator, scenario, live output, report or future version. No peer writer was executed and no peer numeric derivative replaced turnout counts.\n\n[Comparison summary](data/turnout/peer-reconciliation.json), [complete compressed field/object/source-position evidence](data/turnout/source/reciprocal-full-evidence.json.gz), [peer capture inventory](data/turnout/source/peer-capture-v1/inventory.json), and [prior turnout body inventory](data/turnout/source/history/pre-reciprocal-v1/inventory.json) retain exact tested scope and adapters. The latter restores every one of the 4,343 prior owned bodies, including the old manifest, validation, scripts and every original-first witness target. Original response entities remain once, pinned by stored/raw hashes.\n\n'''
 report+=f'''| Source-core comparison | Actual tested scope |\n|---|---:|\n| Equal full original entities and full extracted texts | {c['shared_originals']} (including all 72 ZIP members) |\n| Equal full original receipt objects | 48 |\n| County candidate/Misc. positions; statewide abstract footers | 864; 4 |\n| Statistical participation source group records; monthly registration rows including totals | {c['participation_group_rows']}; {c['monthly_source_rows']} |\n| Shared native normalized objects examined under explicit schema adapter | {c['shared_native_objects']} |\n| Shared candidate cells; mapped control comparisons | {c['shared_candidate_cells']}; {c['shared_control_comparisons']} |\n| Unique complete raw CSV records / original raw fields | {c['unique_raw_CSV_records']} / {c['unique_raw_CSV_fields']} |\n| Multnomah 2024 complete raw CSV records / fields (subset above) | 856 / 11,128 |\n| Full source method lane objects checked against own original rows | {c['method_rows']} |\n| Full known-source native order; complete county sensitivity orders independently recalculated from peer source counts | 510 rows; 14 orders |\n\n'''
 report+='''Raw text checks cover 7,459 objects/nested rows: 6,748 match equal full original text, 432 match retained turnout source observations, and 279 match the exact frozen turnout OCR text and source-line positions. The OCR bindings were resolved from the literal extraction paths; they retain OCR uncertainty and do not establish equal parsing/normalization. These are comparison operations, not unique candidate/administrative fields. The full proof separately records unique raw rows. Every normalized object's schema, source positions, literal controls, methods, null/missing state, overlap and administrative disposition is examined or explicitly marked outside/unmapped. Source-only/unparsed objects remain in the inventories; archive completeness is distinct from native contest closure.\n\nThe full 2024 known-source vectors, candidate controls, overlapping Multnomah PDF/CSV presentations, all 36 county parent vectors, six nonadditive vice-presidential columns, 510 ballot/control rows, complete descending orders, top15, exact integer 80% predecessor/crossing and remainders agree under explicit adapters. Peer source-local tie keys and turnout's versioned FIPS/native keys are separately recalculated; the latter order agrees. The 115/116 combined Clackamas row remains indivisible. No current identity or polygon equivalence follows.\n\nHistorical closure is **16/13/12** parents in turnout versus **16/13/13** in the captured baseline (2020 Senate / 2022 Senate / 2022 governor). For 2020, turnout closes Harney while the peer closes Coos; the retained source-position maps show both original observations. The peer adds 2022 Wasco governor from a direct raster reading; turnout's incomplete normalization remains unchanged. Tillamook's named headings and all source-group rows are retained in the comparison. One candidate difference is confined to unclosed Douglas 2022. The broader control adapter records **17 unequal comparisons** there: the 16 literal control differences already documented by the reverse peer proof plus a repeated heading-undervote representation of the same source scope. This is not 17 newly discovered independent source fields. All affected raw positions and both values are preserved; these working groups remain excluded from closed native orders. No count/source/order repair was warranted by this bounded comparison.\n\nBenton's 2020 ZIP member (115 state-office pages) remains separate from the recovered 262-page federal original and the separate full 189-page 2022 original. Washington text/OCR/word boxes/visual readings retain their positions and uncertainty. The Washington presidential 301,104 versus overall-header 301,105 ballot discrepancy, Wasco 1,831 versus 1,830 office-specific observation, statewide participation/current-history conflicts, generic Misc. scope and choice-specific Multnomah counters remain qualified. No residual allocation, named-write-in eligibility or missing-party inference was introduced.\n\n[Offline rebuild evidence](data/turnout/source/offline-rebuild.json) records nine frozen original scripts executed in isolation without network or peer code and verifies **all 4,343 original-first bodies byte-exact**, with retained OCR/visual readings as inputs. The [negative-fixture proof](data/turnout/source/corruption-fixtures.json), [current validator](data/turnout/scripts/validate.py), [final seal](data/turnout/finalseal.json), and complete self-only-excluded manifest cover the final package. Failed checker versions and exact failures remain in [review-development](data/turnout/source/review-development/): Umatilla list/header representation, nested source-position arrays and the literal vice-presidential Rudolph Ware label required checker adapters, not producer vote changes. The premature preseal-link check and the cross-contest geography-key uniqueness check are also retained with their exact failures; the final observation identity is (source key, contest, literal unit, presentation).\n\nCanonical complete statewide native order/top15/min80/priority/remainder remain **null**: the 31 unclosed parents still contain 1,115,972 votes and unknown native membership. The 510-row known-source and 36-county results remain separate qualified sensitivities. Coordinator acceptance, current source/geometry approval, November IDs/returns/cadence, eligible write-in scope and calibration remain false or unknown.\n'''
 (S/'turnout.md').write_text(report)
 schema=O.read('data/turnout/source/SCHEMA.md').decode()
 schema+='''\n## Reciprocal review and acyclic current sealing\n\nThe original phase documentation above is historical. Native `unit_key` identifies a source geography and can repeat across separate Senate/governor records; observation uniqueness is the composite (source_key, contest, unit_literal, presentation). Never deduplicate across contests. Its exact report/schema/scripts/manifest/validation and all witness targets restore via `source/history/pre-reciprocal-v1/inventory.json` and ordered `bodies-000.tar.gz`; immutable original response references remain once by exact hash. Never compare a historical witness only to later overwritten paths. `scripts/reciprocal.py` verifies each frozen old manifest target and witness body and reads the captured repaired peer package from `source/peer-capture-v1/`, never peer live paths. All 600 bodies are frozen provenance; only the explicit source-core objects/fields/positions/orders in `peer-reconciliation.json` and `source/reciprocal-full-evidence.json.gz` are compared semantically. The compressed full proof is lossless UTF-8 JSON; its raw/stored hash and byte count are in the summary. Full raw original source bytes and request/response receipts remain available by immutable pointers.\n\nAdapters explicitly map zero/one-based abstract columns, literal county/FIPS/native labels, differently named controls, Umatilla list/headers, CSV choice dictionaries, nonadditive overlapping presentations and two tie-key schemes. Missing fields are not zeros; unclosed/source-only/OCR objects are explicit. The 17 Douglas control comparisons include one repeated heading-undervote representation beyond the reverse proof's 16 literal labels. Unique original fields are counted by raw record position, never per repeated derived control. Full-object examination is not a claim that different schemas, locators, extraction coverage or peer model fields are identical.\n\nCurrent reproduction (from the Oregon directory; no network, no peer writers, no caches):\n\n```sh\nPYTHONDONTWRITEBYTECODE=1 python3 -B data/turnout/scripts/offline_rebuild.py\nPYTHONDONTWRITEBYTECODE=1 python3 -B data/turnout/scripts/reciprocal.py\nPYTHONDONTWRITEBYTECODE=1 python3 -B data/turnout/scripts/review_layer.py\nPYTHONDONTWRITEBYTECODE=1 python3 -B data/turnout/scripts/corruption_fixtures.py\nPYTHONDONTWRITEBYTECODE=1 python3 -B data/turnout/scripts/validate.py\n```\n\n`offline_rebuild.py` executes the nine frozen original extraction/build/report scripts in a temporary isolated tree using frozen full original receipts and immutable byteparts. Every old body must match byte-exact. OCR/visual readings are retained locators, not freshly repeated raster reads. `review_layer.py` adds only report/schema/peer-status metadata to the independently extracted phase; it must not change counts, source positions, orders, parent arrays or nulls. Current build.py/report.py are original-phase writers and must be used through the isolated reconstruction or followed by the review layer. Historical old seal.py is retained only as a historical writer; do not invoke it on the current package.\n\n`final_package.py --seal` generates current validation, finalseal and the complete asset manifest. The current manifest excludes **only itself**. Validation/finalseal have no reverse current-manifest digest, so there is no digest cycle. `final_package.py` without flags verifies current exact membership, all hashes/byte bounds, historical manifests and witnesses, peer capture, full source reconstruction and hierarchy/order invariants read-only; run it after sealing, then freeze bytes. Every stored artifact is strictly below 40,000,000 bytes. Coordinator is the sole acceptance authority; canonical statewide native priority and current/legal/geographic acceptance remain unavailable/false.\n'''
 (T/'source/SCHEMA.md').write_text(schema)
 print(json.dumps(dict(status='metadata_layer_written',priority_counts_unchanged=True,peer_agent_id=review['peer_agent_id'])))
if __name__=='__main__':main()
